import static com.kms.katalon.core.testobject.ObjectRepository.findTestObject
import com.kms.katalon.core.webservice.keyword.WSBuiltInKeywords as WS
import groovy.json.JsonSlurper

// 1. CREATE (POST Request)
// Send POST request to create a new object
def postResponse = WS.sendRequest(findTestObject('API/REST/RestAPICollection/POST_RestAPI'))
WS.verifyResponseStatusCode(postResponse, 200)

// Parse JSON response to grab the dynamic ID generated by the server
def jsonSlurper = new JsonSlurper()
def postResult = jsonSlurper.parseText(postResponse.getResponseBodyContent())
String createdId = postResult.id
println("Created Object ID: " + createdId)


// 2. READ (GET Request)
// Verify the newly created item exists
def getResponse = WS.sendRequest(findTestObject('API/REST/RestAPICollection/GET_RestAPI'))
WS.verifyResponseStatusCode(getResponse, 200)


// 3. UPDATE (PUT Request)
// Update the object using the ID we grabbed from Step 1
def putObject = findTestObject('API/REST/RestAPICollection/PUT_RestAPI')

// Dynamically replace the {your_object_id} in your URL path
putObject.setRestUrl("https://api.restful-api.dev/collections/products/objects/" + createdId)

def putResponse = WS.sendRequest(putObject)
WS.verifyResponseStatusCode(putResponse, 200)


// 4. DELETE (DELETE Request)
// Clean up and remove the object using its ID
def deleteObject = findTestObject('API/REST/RestAPICollection/DELETE_RestAPI')

// Dynamically replace the {your_object_id} in your URL path
deleteObject.setRestUrl("https://api.restful-api.dev/collections/products/objects/" + createdId)

def deleteResponse = WS.sendRequest(deleteObject)
WS.verifyResponseStatusCode(deleteResponse, 200)

println("CRUD Workflow Completed Successfully! 🎉")